import {Compass,Trophy,Heart,BookOpen,User,Store,Settings,MapPin,Search,LocateFixed,ArrowUpRight,Coffee,ChevronRight,Route,Star,ShieldCheck,Ticket,LogOut,Info,CheckCircle2,Camera,Plus,Trash2,RefreshCw,Menu,Navigation,SlidersHorizontal,WalletCards,Award,Copy} from 'lucide-react';
import {SidebarProvider,Sidebar,SidebarContent,SidebarFooter,SidebarTrigger} from '@/components/ui/sidebar';
