const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n||0);
const grade=(n:any)=>n==null?'—':Number(n).toFixed(2).replace('.',',');
const day=(s:string)=>new Date(s).toLocaleDateString('pt-BR');
const routes:any={explore:'/',ranking:'/ranking',places:'/meus-lugares',guide:'/guia',profile:'/perfil',business:'/estabelecimento',admin:'/admin',about:'/sobre'};
const labels:any={explore:'Explorar paradas',ranking:'Ranking da estrada',places:'Meus lugares',guide:'Guia de Estrada',profile:'Meu perfil',business:'Minha parada',admin:'Administração',about:'Bem-vindo à estrada'};
const status:any={pending:'Aguardando aprovação',approved:'Aprovado',rejected:'Rejeitado',blocked:'Bloqueado'};
function SelectBox({value,onChange,options,placeholder,className}:{value:string,onChange:(v:string)=>void,options:any[],placeholder?:string,className?:string}){return <Select value={value||'all'} onValueChange={onChange}><SelectTrigger className={className||'filter'}><SelectValue placeholder={placeholder}/></SelectTrigger><SelectContent>{options.map(o=><SelectItem value={typeof o==='string'?o:o.value} key={typeof o==='string'?o:o.value}>{typeof o==='string'?o:o.label}</SelectItem>)}</SelectContent></Select>}
function Field({label,name,defaultValue,required,type='text',full=false,...rest}:any){return <label className={'field '+(full?'full':'')}>{label}<input name={name} defaultValue={defaultValue??''} required={required} type={type} {...rest}/></label>}
function Blank({title,children}:{title:string,children:React.ReactNode}){return <div className="empty"><Coffee size={36}/><h2>{title}</h2><p>{children}</p></div>}
function distance(a:number[],b:any){const r=Math.PI/180,x=Math.sin((b.lat-a[0])*r/2)**2+Math.cos(a[0]*r)*Math.cos(b.lat*r)*Math.sin((b.lng-a[1])*r/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
export default function BebidaApp(){
const [view,setView]=useState('explore'),[data,setData]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[query,setQuery]=useState(''),[state,setState]=useState('all'),[city,setCity]=useState('all'),[region,setRegion]=useState('all'),[radius,setRadius]=useState('all'),[loc,setLoc]=useState<number[]|null>(null),[locBusy,setLocBusy]=useState(false),[selected,setSelected]=useState<any>(null),[modal,setModal]=useState(''),[authMode,setAuthMode]=useState('login'),[role,setRole]=useState('TRAVELER'),[consent,setConsent]=useState(false),[formError,setFormError]=useState(''),[edit,setEdit]=useState<any>(null),[photo,setPhoto]=useState(''),[uploading,setUploading]=useState(false),[accept,setAccept]=useState(false),[code,setCode]=useState(''),[reviewStage,setReviewStage]=useState(0),[ratings,setRatings]=useState<number[]>(Array(5).fill(0)),[confirm,setConfirm]=useState<any>(null),[campaignId,setCampaignId]=useState(''),[qr,setQr]=useState(''),[newCampaign,setNewCampaign]=useState(false),[geoRequired,setGeoRequired]=useState(false),[publicRanking,setPublicRanking]=useState(true),[locked,setLocked]=useState(false);
const [reviewQuestions,setReviewQuestions]=useState<any[]>([]),[formId,setFormId]=useState(''),[mobilePanel,setMobilePanel]=useState('list'),[filtersOpen,setFiltersOpen]=useState(false),[pixDeposit,setPixDeposit]=useState<any>(null);
const [guestCpf,setGuestCpf]=useState(''),[guestConsent,setGuestConsent]=useState(false),[reviewAccess,setReviewAccess]=useState(''),[qrFull,setQrFull]=useState(false);const qrRef=useRef<HTMLDivElement>(null);
const contextRef=useRef<any>(null);contextRef.current={data,query};
useEffect(()=>{const ctx=(document as any).modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'search_road_stops',title:'Buscar paradas',description:'Filtra as paradas por nome, cidade, estado ou prato e abre a tela Explorar.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:150}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input:any){if(!input||typeof input.query!=='string'||input.query.length>150)throw new Error('Informe uma busca de até 150 caracteres.');setQuery(input.query);setState('all');setCity('all');setRegion('all');setRadius('all');setView('explore');history.pushState({},'','/');await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return {query:input.query,view:'explore'};}},{name:'list_road_stops',title:'Consultar paradas',description:'Consulta as paradas aprovadas da campanha carregada. Não retorna dados pessoais.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {stops:(contextRef.current.data?.businesses||[]).map((b:any)=>({id:b.id,name:b.name,city:b.city,state:b.state,dish:b.dishName,score:b.score,demo:!!b.demo}))}}}];for(const t of tools)Promise.resolve(ctx.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});return()=>lifecycle.abort()},[]);
const requestSequence=useRef(0);
const reload=useCallback(async()=>{const sequence=++requestSequence.current;try{const r=await fetch((view==='admin'?'/api/admin-data':'/api/data')+(campaignId?'?campaign='+encodeURIComponent(campaignId):''));const d:any=await r.json();if(sequence!==requestSequence.current)return;if(!r.ok)throw Error(d.error);setData(d);setError('')}catch(e){if(sequence===requestSequence.current)setError((e as Error).message)}},[campaignId,view]);
useEffect(()=>{const sync=()=>setView(Object.keys(routes).find(k=>routes[k]===location.pathname)||'explore');sync();window.addEventListener('popstate',sync);const token=new URLSearchParams(location.search).get('token');if(token){setCode(token);setModal('review');setBusy(true);fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'resolveToken',code:token})}).then(async r=>{const d:any=await r.json();if(!r.ok)throw Error(d.error);setEdit({...d.business,reviewCampaign:d.campaign});setCampaignId(d.campaign.id)}).catch(e=>setFormError(e.message)).finally(()=>setBusy(false));}return()=>window.removeEventListener('popstate',sync)},[]);
useEffect(()=>{reload();const timer=setInterval(()=>{if(document.visibilityState==='visible')reload()},15000);return()=>clearInterval(timer)},[reload]);
useEffect(()=>{if(data?.campaign){setGeoRequired(!!data.campaign.geoRequired);setPublicRanking(!!data.campaign.publicRanking);setLocked(!!data.campaign.locked)}},[data?.campaign?.id]);
const nav=(v:string)=>{setQuery('');setRadius('all');setView(v);history.pushState({},'',routes[v]);window.scrollTo(0,0)};
async function action(action:string,p:any={}){const r=await fetch(view==='admin'?'/api/admin-action':'/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,campaignId:data?.campaign.id,...p})});const d:any=await r.json();if(!r.ok)throw Error(d.error);return d}
async function run(a:string,p:any={},message='Salvo com sucesso.'){setBusy(true);try{const d=await action(a,p);await reload();if(message)toast.success(message);return d}catch(e){toast.error((e as Error).message);return null}finally{setBusy(false)}}
function open(m:string,obj:any=null){setModal(m);setEdit(obj);setFormError('');setPhoto(obj?.dishPhoto||obj?.photo||'');setAccept(!!obj);if(m==='review'){setReviewStage(0);setRatings(Array(5).fill(0));setReviewQuestions([]);setFormId('');setReviewAccess('');setGuestCpf('');setGuestConsent(false)}if(m==='qr')setQrFull(false)}
function login(r='TRAVELER',register=false){setRole(r);setAuthMode(register?'register':'login');setConsent(false);open('auth')}
async function locate(){setLocBusy(true);return new Promise<number[]|null>(resolve=>{if(!navigator.geolocation){toast.error('Seu navegador não oferece localização.');setLocBusy(false);resolve(null);return}navigator.geolocation.getCurrentPosition(p=>{const pos=[p.coords.latitude,p.coords.longitude];setLoc(pos);setLocBusy(false);resolve(pos)},()=>{toast.error('Localização indisponível. Você pode continuar buscando por cidade.');setLocBusy(false);resolve(null)},{enableHighAccuracy:true,timeout:15000})})}
async function submit(e:React.FormEvent<HTMLFormElement>,a:string,extra:any={}){e.preventDefault();setBusy(true);setFormError('');const p=Object.fromEntries(new FormData(e.currentTarget));try{await action(a,{...p,...extra});setModal('');await reload();toast.success(a==='register'?'Conta criada. Boa viagem!':'Salvo com sucesso.')}catch(e){setFormError((e as Error).message)}finally{setBusy(false)}}
async function upload(file?:File){if(!file)return;setUploading(true);try{const f=new FormData();f.append('file',file);const r=await fetch(view==='admin'?'/api/admin-upload':'/api/upload',{method:'POST',body:f});const d:any=await r.json();if(!r.ok)throw Error(d.error);setPhoto(d.url);toast.success('Foto enviada. Salve o formulário para aplicar.')}catch(e){toast.error((e as Error).message)}finally{setUploading(false)}}
async function tokenCheck(){setBusy(true);setFormError('');try{
const response=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'resolveToken',code})});const resolved:any=await response.json();if(!response.ok)throw Error(resolved.error);
if(edit?.id&&edit.id!==resolved.business.id)throw Error('Este token pertence a outra parada.');
const c=resolved.campaign;setEdit({...resolved.business,reviewCampaign:c});setCampaignId(c.id);
const pos=c.geoRequired?(loc||await locate()):loc;
const signedTraveler=data?.user?.role==='TRAVELER';
const result=await action(signedTraveler?'validateToken':'guestValidate',{campaignId:c.id,businessId:resolved.business.id,code,cpf:guestCpf,consent:guestConsent,lat:pos?.[0],lng:pos?.[1]});
setGuestCpf('');setReviewAccess(result.reviewAccess||'');setFormId(result.formId);setReviewQuestions(result.questions);setRatings(Array(5).fill(0));setReviewStage(1)
}catch(e){setFormError((e as Error).message)}finally{setBusy(false)}}
async function closeQrFull(){if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});setQrFull(false)}

const user=data?.user,camp=data?.campaign,isAdmin=view==='admin'&&data?.adminAuthenticated===true;const businesses:any[]=data?.businesses||[];const filtered=businesses.filter(b=>{const text=[b.name,b.city,b.state,b.dishName].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),q=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return text.includes(q)&&(state==='all'||b.state===state)&&(city==='all'||b.city===city)&&(region==='all'||b.region===region)&&(radius==='all'||!loc||distance(loc,b)<=Number(radius))});const availableStates=Array.from(new Set(businesses.map(b=>b.state))).sort(),cities=Array.from(new Set(businesses.filter(b=>state==='all'||state===b.state).map(b=>b.city))).sort();
function card(b:any,guide=false){return <article className="stop-card" key={b.id}><div className="card-main"><img src={b.dishPhoto||b.photo||'/coffee.jpg'} className="card-photo" alt={b.demo?'Foto ilustrativa do combo':b.dishName}/><div className="card-copy"><div className="flexline spread"><span className="pill" style={{fontSize:11,padding:'4px 7px'}}><Route size={11}/>{b.road||b.state}</span><button aria-label={data?.favorites?.includes(b.id)?'Remover dos favoritos':'Salvar parada'} onClick={()=>user?run('favorite',{businessId:b.id,remove:data.favorites?.includes(b.id)},'Favoritos atualizados.'):login()}><Heart size={17} fill={data?.favorites?.includes(b.id)?'#d6a248':'none'} color="#819274"/></button></div><h3><button onClick={()=>setSelected(b)}>{b.name}</button></h3><div className="location"><MapPin size={12}/>{b.city} · {b.state}</div><p className="dish">{b.dishName}</p>{!!b.demo&&<div className="modebadge">DEMONSTRAÇÃO</div>}<span className="price">{money(camp?.price)}<del>{money(b.normalPrice)}</del></span>{guide&&<p className="dish">{b.address}</p>}</div></div><div className="card-foot"><span className="flexline" style={{gap:5}}><Star size={13} color="#c69237" fill={b.score?'#c69237':'none'}/>{b.score?grade(b.score):'Sem avaliações'}{loc&&` · ${distance(loc,b).toFixed(1)} km`}</span><button onClick={()=>setSelected(b)}>Ver parada <ArrowUpRight size={14}/></button></div></article>}
const navItems=[['explore',Compass,'Explorar'],['ranking',Trophy,'Ranking'],['places',Heart,'Meus lugares'],['guide',BookOpen,'Guia de Estrada'],['profile',User,'Meu perfil']] as const;
return <SidebarProvider style={{'--sidebar-width':'232px'} as React.CSSProperties}><Toaster position="top-right" richColors/><Sidebar className="border-0"><SidebarContent className="gap-0"><a className="brand" href="/" onClick={e=>{e.preventDefault();nav('explore')}}><img src="/logo.png" alt="Caneca com uma estrada"/><span>Bebida<small>DE ESTRADA</small></span></a><div className="side-label">SUA PRÓXIMA PARADA</div><nav className="navlinks">{navItems.map(([key,Icon,label])=><button key={key} className={'navlink '+(view===key?'active':'')} onClick={()=>nav(key)}><Icon size={19}/>{label}</button>)}</nav><div className="side-label" style={{marginTop:28}}>FAÇA PARTE</div><nav className="navlinks"><button className={'navlink '+(view==='business'?'active':'')} onClick={()=>nav('business')}><Store size={19}/>Área da parada</button></nav><div className="side-bottom"><div className="campaign-box"><Coffee size={25} color="#efbb64"/><b>Uma pausa. Muitos sabores.</b><p>Um prato especial + um café. Descubra o próximo no seu caminho.</p><button className="nav-footer-link" style={{padding:'12px 0 0',color:'#efc578'}} onClick={()=>nav('about')}>Conheça a campanha ↗</button></div><div className="side-footer"><Route size={16}/>Estrada, café e descoberta.</div></div></SidebarContent><SidebarFooter><button className="nav-footer-link" onClick={()=>open('privacy')}>Privacidade e créditos</button></SidebarFooter></Sidebar>
<div className="shell"><header className="topbar"><a className="mobile-wordmark" href="/" onClick={e=>{e.preventDefault();nav('explore')}}><img src="/icons/icon-192.png" alt=""/><span>Bebida de Estrada</span></a><div className="breadcrumb"><SidebarTrigger className="md:hidden"/><span>Bebida de Estrada</span><ChevronRight size={13}/><b style={{color:'#4f6650'}}>{view==='explore'?'Explorar':labels[view]}</b></div><div className="account"><Pwa/>{user?<><span className="name" style={{fontSize:14}}>Olá, {user.name.split(' ')[0]}</span><button className="avatar" onClick={()=>nav('profile')}>{user.name.slice(0,1).toUpperCase()}</button></>:<button className="btn small" onClick={()=>login()}>Entrar <User size={15}/></button>}</div></header>
<main className={'content view-'+view}>{error?<div className="section-card"><h2>Vamos tentar novamente?</h2><p>{error}</p><button className="btn" onClick={reload}><RefreshCw size={15}/>Recarregar</button></div>:!data?<div className="loading">Preparando suas próximas paradas…</div>:<>
{view==='explore'&&<><div className="intro"><div><div className="eyebrow">O MELHOR DA VIAGEM ESTÁ NO CAMINHO</div><h1>Sua próxima parada tem sabor.</h1><p>Encontre um bom prato, um café quentinho e uma nova história.</p></div><span className="pill gold"><Coffee size={14}/>Campanha {camp.name.includes('2026')?'2026':camp.name}</span></div><div className="searchbox"><Search size={21} color="#77866b"/><input aria-label="Buscar paradas" placeholder="Para onde você está indo? Busque cidade, parada ou prato" value={query} onChange={e=>setQuery(e.target.value)}/><button className="btn primary" disabled={locBusy} onClick={locate}><LocateFixed size={17}/><span>{locBusy?'Localizando…':'Perto de mim'}</span></button></div><div className="mobile-explore-tools"><Tabs value={mobilePanel} onValueChange={setMobilePanel}><TabsList><TabsTrigger value="list">Paradas ({filtered.length})</TabsTrigger><TabsTrigger value="map">Mapa</TabsTrigger></TabsList></Tabs><button className="btn small" aria-expanded={filtersOpen} aria-controls="explore-filters" onClick={()=>setFiltersOpen(!filtersOpen)}><SlidersHorizontal size={16}/>Filtros{[state,city,region,radius].filter(v=>v!=='all').length>0?' · '+[state,city,region,radius].filter(v=>v!=='all').length:''}</button></div><div id="explore-filters" className={'filters explore-filters '+(filtersOpen?'is-open':'')}><SelectBox value={state} onChange={v=>{setState(v);setCity('all')}} options={[{value:'all',label:'Todos os estados'},...availableStates]}/><SelectBox value={city} onChange={setCity} options={[{value:'all',label:'Todas as cidades'},...cities]}/><SelectBox value={region} onChange={setRegion} options={[{value:'all',label:'Todas as regiões'},'Sudeste','Sul','Nordeste','Norte','Centro-Oeste']}/><SelectBox value={radius} onChange={async v=>{if(v!=='all'&&!loc){const pos=await locate();if(!pos)return}setRadius(v)}} options={[{value:'all',label:'Qualquer distância'},...[5,10,25,50,100].map(n=>({value:String(n),label:`Até ${n} km`}))]}/><span className="count">{filtered.length} paradas no caminho</span></div><div className={'workspace mobile-panel-'+mobilePanel}><section className="results-panel"><div className="results-head"><h2>Descubra sua próxima parada</h2><small>{filtered.length} resultados</small></div><div className="cards">{filtered.map(b=>card(b))}{!filtered.length&&<Blank title="Nenhuma parada por aqui ainda">Tente outra cidade ou aumente o raio da busca.</Blank>}</div></section><div className="mapwrap"><RoadMap businesses={filtered} onSelect={setSelected} selected={selected?.id} location={loc} tileUrl={data.tileUrl} attribution={data.tileAttribution}/><div className="map-badge"><MapPin size={16}/>Sabores pelo caminho</div><div className="map-note"><Coffee size={26} color="#b58c49"/><div><b>O mesmo preço. Uma descoberta em cada parada.</b><small>Prato participante + café por {money(camp.price)}</small></div></div></div></div><p className="bottom-note"><Info size={15}/>{businesses.some(b=>b.demo)?'Dados demonstrativos · Nomes usados como exemplos, sem parceria. Fotos ilustrativas e posições aproximadas.':'Paradas aprovadas da campanha. Consulte ingredientes e disponibilidade no local.'}</p></>}
{view==='ranking'&&<><div className="intro"><div className="title"><div className="eyebrow">QUEM PROVA, ESCOLHE</div><h1>Ranking da estrada</h1><p>O sabor do prato e a experiência com o café, lado a lado.</p></div><span className="pill"><RefreshCw size={13}/>Atualiza a cada 15 s</span></div><div className="rank-hero"><Trophy size={48} color="#ebbf69"/><div><h2>Cada parada tem uma chance de conquistar você.</h2><p>60% lanche · 40% café · 5 perguntas por avaliação</p></div></div><div className="filters"><SelectBox value={state} onChange={setState} options={[{value:'all',label:'Ranking nacional'},...availableStates]}/><SelectBox value={city} onChange={setCity} options={[{value:'all',label:'Todas as cidades'},...cities]}/><SelectBox value={region} onChange={setRegion} options={[{value:'all',label:'Todas as regiões'},'Sudeste','Sul','Nordeste','Norte','Centro-Oeste']}/></div>{!camp.publicRanking&&!isAdmin?<Blank title="O ranking está reservado">A organização publicará os resultados conforme as regras da campanha.</Blank>:<div className="section-card tablewrap ranking-desktop"><Table><TableHeader><TableRow>{['Posição','Parada / combo','Lanche · 60%','Café · 40%','Média do combo','Avaliações'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{filtered.map((b,i)=><TableRow key={b.id}><TableCell><span className="ranknum">{b.score?`${i+1}º`:'—'}</span></TableCell><TableCell><button onClick={()=>setSelected(b)} className="flexline"><img className="small-photo" src={b.dishPhoto||'/coffee.jpg'} alt=""/><span style={{textAlign:'left'}}><b>{b.name}</b><small style={{display:'block',color:'#86927d'}}>{b.city} · {b.dishName}</small></span></button></TableCell><TableCell>{grade(b.dishRating)}</TableCell><TableCell>{grade(b.coffeeRating)}</TableCell><TableCell><b>{grade(b.score)}</b></TableCell><TableCell>{b.reviewCount||0}</TableCell></TableRow>)}</TableBody></Table><p className="bottom-note">Desempate: nota final, {camp.ties.split(',').map((x:string)=>({coffee:'nota do café',count:'quantidade de avaliações',dish:'nota do prato'} as any)[x]).join(', ')}. Paradas sem votos não têm posição.</p></div>}{(camp.publicRanking||isAdmin)&&<div className="ranking-mobile">{filtered.map((b,i)=><button className="ranking-mobile-card" key={b.id} onClick={()=>setSelected(b)}><div className="ranking-mobile-top"><span className="ranknum">{b.score?`${i+1}º`:'—'}</span><img className="small-photo" src={b.dishPhoto||'/coffee.jpg'} alt=""/><div><b>{b.name}</b><small>{b.city} · {b.state}</small></div></div><p>{b.dishName}</p><div className="ranking-mobile-score"><span><strong>{grade(b.score)}</strong><small>Média do combo</small></span><span><strong>{b.reviewCount||0}</strong><small>Avaliações</small></span></div><div className="ranking-mobile-breakdown"><span>Lanche {grade(b.dishRating)} · 60%</span><span>Café {grade(b.coffeeRating)} · 40%</span></div></button>)}{!filtered.length&&<Blank title="Nenhuma parada encontrada">Experimente outros filtros para consultar o ranking.</Blank>}<p className="bottom-note">Média do combo = média do lanche × 0,6 + média do café × 0,4.</p></div>}</>}
{view==='guide'&&<><div className="intro"><div><div className="eyebrow">LEVE OS SABORES COM VOCÊ</div><h1>Guia de Estrada</h1><p>Uma viagem pelas paradas, cidade por cidade.</p></div></div>{availableStates.map(s=><section key={s}><h2 style={{fontFamily:'Georgia',fontSize:27,margin:'25px 0'}}>{s==='MG'?'Minas Gerais':s==='SP'?'São Paulo':s}</h2>{Array.from(new Set(businesses.filter(b=>b.state===s).map(b=>b.city))).sort().map(c=><div key={c}><h3 style={{fontSize:17,margin:'20px 0 12px'}}>{c}</h3><div className="guide-grid">{businesses.filter(b=>b.state===s&&b.city===c).map(b=>card(b,true))}</div></div>)}</section>)}</>}
{view==='places'&&<><div className="intro"><div><div className="eyebrow">SEU CADERNO DE VIAGEM</div><h1>Meus lugares</h1><p>As paradas que você guardou e os sabores que já experimentou.</p></div></div>{!user?<div className="section-card"><Blank title="Sua viagem começa aqui">Entre para guardar paradas e consultar suas avaliações.</Blank><button className="btn primary full-button" onClick={()=>login()}>Entrar na minha conta</button></div>:<Tabs defaultValue="saved"><TabsList><TabsTrigger value="saved">Favoritos ({data.favorites?.length||0})</TabsTrigger><TabsTrigger value="visited">Visitados ({data.myReviews?.length||0})</TabsTrigger></TabsList><TabsContent value="saved"><div className="guide-grid">{businesses.filter(b=>data.favorites?.includes(b.id)).map(b=>card(b))}</div>{!data.favorites?.length&&<Blank title="Uma parada para chamar de favorita">Toque no coração de uma parada para encontrá-la aqui.</Blank>}</TabsContent><TabsContent value="visited">{data.myReviews?.map((r:any)=><div className="section-card flexline spread" key={r.id}><div><h3>{r.businessName}</h3><p>{day(r.createdAt)} · {r.status==='valid'?'Avaliação registrada':'Avaliação invalidada pela organização'}</p></div><b>Prato {grade(r.dish)} · Café {grade(r.coffee)}</b></div>)}{!data.myReviews?.length&&<Blank title="O próximo sabor espera por você">Experimente um combo e use o token da parada para avaliar.</Blank>}</TabsContent></Tabs>}</>}
{view==='profile'&&<><div className="intro"><h1>Meu perfil</h1></div>{!user?<div className="section-card"><Blank title="Boa viagem, viajante">Crie sua conta para salvar lugares e participar da campanha.</Blank><div className="flexline"><button className="btn primary" onClick={()=>login('TRAVELER',true)}>Criar conta</button><button className="btn" onClick={()=>login()}>Já tenho uma conta</button></div></div>:<div className="section-card" style={{maxWidth:650}}><div className="flexline spread"><h2>Olá, {user.name}</h2><span className="pill">{isAdmin?'Administrador':user.role==='BUSINESS'?'Estabelecimento':'Viajante'}</span></div><form onSubmit={e=>submit(e,'profile')}><div className="form-grid" style={{marginTop:25}}><Field label="Seu nome" name="name" defaultValue={user.name} required/><Field label="Telefone (opcional)" name="phone" defaultValue={user.phone}/><Field label="E-mail" defaultValue={user.email} disabled/><Field label="CPF protegido" defaultValue={user.cpfLast?'***.***.***-'+user.cpfLast:'Não solicitado para esta conta'} disabled/></div><div className="form-actions"><button className="btn" type="button" onClick={()=>run('logout',{},'Você saiu da conta.')}><LogOut size={15}/>Sair</button><button className="btn primary" disabled={busy}>Salvar perfil</button></div></form></div>}</>}
{view==='business'&&<><div className="intro"><div><div className="eyebrow">BEM-VINDO, ANFITRIÃO</div><h1>Área da parada</h1><p>Cuide do seu combo e acompanhe quem passa por aqui.</p></div>{user&&['BUSINESS','ADMIN','SUPER_ADMIN'].includes(user.role)&&<button className="btn primary" onClick={()=>open('business')}><Plus size={16}/>Cadastrar parada</button>}</div>{!user||user.role==='TRAVELER'?<div className="section-card"><h2>O próximo destino pode ser a sua mesa.</h2><p>Cadastre seu estabelecimento, prepare um combo com o café oficial e receba novos viajantes.</p><button className="btn primary" style={{marginTop:20}} onClick={()=>login('BUSINESS',true)}>Sou estabelecimento</button><button className="btn" style={{marginLeft:10}} onClick={()=>login('BUSINESS')}>Já tenho conta</button></div>:<>{!data.owned?.length&&<Blank title="Sua parada começa aqui">Cadastre seu estabelecimento e aguarde a aprovação da organização.</Blank>}{data.owned?.map((b:any)=>{const pub=businesses.find(x=>x.id===b.id);const tokens=data.tokens?.filter((t:any)=>t.businessId===b.id)||[];return <section key={b.id}><div className="section-card"><div className="flexline spread"><h2>{b.name}</h2><span className="pill gold">{status[b.status]}</span></div><p>{b.city} · {b.state}</p><div className="flexline" style={{marginTop:18}}><button className="btn" onClick={()=>open('business',b)}>Editar parada</button><button className="btn" onClick={()=>open('dish',b)}>Meu combo</button><button className="btn primary" disabled={b.status!=='approved'} onClick={()=>open('tokens',b)}><Ticket size={16}/>Gerar tokens</button></div></div><div className="stats">{[['Posição',pub?.rank?pub.rank+'º':'—'],['Nota do prato',grade(pub?.dishRating)],['Nota do café',grade(pub?.coffeeRating)],['Avaliações',pub?.reviewCount||0]].map(([s,n])=><div className="stat" key={s}><span>{s}</span><strong>{n}</strong></div>)}</div><div className="section-card"><h2>Tokens de avaliação</h2><p>{tokens.length} gerados · {tokens.filter((t:any)=>t.status==='utilizado').length} utilizados</p>{tokenTable(tokens)}</div></section>})}</>}</>}
{view==='admin'&&<><div className="intro"><div><div className="eyebrow">ORGANIZAÇÃO DA CAMPANHA</div><h1>Administração</h1><p>Paradas, participantes e cada detalhe da competição.</p></div>{isAdmin&&<div className="flexline"><SelectBox value={camp.id} onChange={setCampaignId} options={(data.campaigns||[]).map((c:any)=>({value:c.id,label:c.name}))}/><button className="btn small" onClick={()=>run('adminLogout',{},'Você saiu do painel.')}><LogOut size={15}/>Sair do painel</button></div>}</div>{!isAdmin?<div className="section-card admin-gate"><ShieldCheck size={35}/><h2>Acesso da organização</h2><p>Informe a senha administrativa para abrir o painel.</p><form onSubmit={e=>submit(e,'adminLogin')}><Field label="Senha de administrador" name="password" type="password" required maxLength={128} autoComplete="current-password"/>{formError&&<div className="alert error" role="alert">{formError}</div>}<button className="btn primary full-button" disabled={busy}>{busy?'Verificando…':'Entrar no painel'}</button></form></div>:<><div className="stats">{[['Paradas cadastradas',data.allBusinesses.length],['Aguardando aprovação',data.allBusinesses.filter((b:any)=>b.status==='pending').length],['Avaliações válidas',data.reviews.filter((r:any)=>r.status==='valid').length],['Fundo da premiação',money(camp.fund*camp.prizePercent/100)]].map(([s,n])=><div className="stat" key={s}><span>{s}</span><strong>{n}</strong></div>)}</div><Tabs defaultValue="businesses"><div className="admin-tabs"><TabsList>{[['businesses','Paradas'],['campaign','Campanha'],['tokens','Tokens'],['reviews','Avaliações'],['questions','Perguntas'],['travelers','Viajantes'],['demo','Demonstração'],['audit','Auditoria']].map(([v,l])=><TabsTrigger key={v} value={v}>{l}</TabsTrigger>)}</TabsList></div>
<TabsContent value="prize"><div className="section-card prize-panel"><div className="flexline spread"><div><div className="eyebrow">FUNDO DE PREMIAÇÃO</div><h2>{money((data.prizePool?.totalCents||0)/100)}</h2><p>Valor integral reservado para o vencedor elegível.</p></div><Award size={34} color="#b58c49"/></div><p className="bottom-note">Elegibilidade: no mínimo 100 avaliações válidas. O vencedor é definido pela maior média; em empate, mais avaliações e depois quem atingiu 100 primeiro.</p><Table><TableHeader><TableRow><TableHead>Estabelecimento</TableHead><TableHead>Média</TableHead><TableHead>Avaliações</TableHead></TableRow></TableHeader><TableBody>{(data.prizeRanking||[]).map((r:any)=><TableRow key={r.businessId}><TableCell>{r.name}</TableCell><TableCell>{grade(r.average)}</TableCell><TableCell>{r.reviewCount}</TableCell></TableRow>)}</TableBody></Table><button className="btn danger" disabled={busy||camp.status==='encerrada'} onClick={()=>setConfirm({action:'closeCampaign',title:'Encerrar campanha e fechar o prêmio?',description:'Essa ação é irreversível. O fundo será congelado e o estabelecimento vencedor será registrado.'})}>Encerrar campanha e definir vencedor</button>{data.prizePool?.status==='closed'&&<div className="alert" style={{marginTop:16}}><b>Campanha encerrada.</b> Vencedor: {(data.prizeRanking||[]).find((r:any)=>r.businessId===data.prizePool.winnerBusinessId)?.name||'Nenhum estabelecimento elegível'} · Prêmio {money((data.prizePool.totalCents||0)/100)}</div>}</div></TabsContent><TabsContent value="businesses"><div className="section-card"><div className="flexline spread"><h2>Estabelecimentos</h2><button className="btn" onClick={()=>open('business')}><Plus size={15}/>Nova parada</button></div><Table><TableHeader><TableRow><TableHead>Parada</TableHead><TableHead>Status</TableHead><TableHead>Ações</TableHead></TableRow></TableHeader><TableBody>{data.allBusinesses.map((b:any)=><TableRow key={b.id}><TableCell><b>{b.name}</b><small style={{display:'block'}}>{b.city} · {b.demo?'Demonstração':b.cnpj}</small></TableCell><TableCell><span className="pill">{status[b.status]}</span></TableCell><TableCell><div className="flexline">{b.status!=='approved'&&<button className="btn small" disabled={busy} onClick={()=>run('businessStatus',{id:b.id,status:'approved'},'Parada aprovada.')}>Aprovar</button>}{b.status==='pending'&&<button className="btn small" onClick={()=>run('businessStatus',{id:b.id,status:'rejected'})}>Rejeitar</button>}{b.status==='approved'&&<button className="btn small" onClick={()=>run('businessStatus',{id:b.id,status:'blocked'})}>Bloquear</button>}<button className="btn small" onClick={()=>open('business',b)}>Editar</button><button className="btn small" onClick={()=>open('dish',b)}>Combo</button><button className="btn small" onClick={()=>open('tokens',b)}>Tokens</button><button className="btn small danger" aria-label={'Excluir '+b.name} onClick={()=>setConfirm({action:'deleteBusiness',p:{id:b.id},title:'Excluir esta parada?',description:'A parada, seus tokens e suas avaliações serão removidos.'})}><Trash2 size={14}/></button></div></TableCell></TableRow>)}</TableBody></Table></div></TabsContent>
<TabsContent value="campaign"><div className="section-card"><div className="flexline spread"><h2>{camp.name}</h2><button className="btn" onClick={()=>{setNewCampaign(true);open('campaign')}}>Nova campanha</button></div><p>{camp.brand} · {money(camp.price)} por combo · {camp.status}</p><div className="flexline" style={{marginTop:20}}><button className="btn primary" onClick={()=>{setNewCampaign(false);setGeoRequired(!!camp.geoRequired);setPublicRanking(!!camp.publicRanking);setLocked(!!camp.locked);open('campaign',camp)}}>Configurar campanha</button><button className="btn danger" onClick={()=>setConfirm({action:'campaign',p:{...camp,status:'encerrada'},title:'Encerrar campanha?',description:'Novos votos serão bloqueados e tokens disponíveis serão expirados.'})}>Finalizar campanha</button></div><p style={{marginTop:20}}>Arrecadado: {money(camp.fund)} · Premiação: {camp.prizePercent}% · Distribuidora: {100-camp.prizePercent}%</p></div></TabsContent>
<TabsContent value="tokens"><div className="section-card"><h2>Tokens da campanha</h2>{tokenTable(data.tokens||[])}</div></TabsContent>
<TabsContent value="reviews"><div className="section-card"><h2>Avaliações</h2><Table><TableHeader><TableRow>{['Parada / viajante','Prato','Café','Status','Ação'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{data.reviews.map((r:any)=><TableRow key={r.id}><TableCell><b>{r.businessName}</b><small style={{display:'block'}}>{r.userName} · {day(r.createdAt)}</small></TableCell><TableCell>{grade(r.dish)}</TableCell><TableCell>{grade(r.coffee)}</TableCell><TableCell>{r.status==='valid'?'Válida':'Invalidada'}</TableCell><TableCell>{r.status==='valid'&&<button className="btn small danger" onClick={()=>setConfirm({action:'invalidateReview',p:{id:r.id},title:'Invalidar avaliação?',description:'A nota sairá do ranking. O token continuará utilizado e um novo voto não será permitido.'})}>Invalidar</button>}</TableCell></TableRow>)}</TableBody></Table></div></TabsContent>
<TabsContent value="questions"><QuestionBank questions={data.questions||[]} onEdit={q=>open('question',q)}/></TabsContent><TabsContent value="travelers"><div className="section-card"><h2>Contas cadastradas</h2><Table><TableHeader><TableRow>{['Nome','E-mail','Tipo','CPF protegido'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{data.users.map((u:any)=><TableRow key={u.id}><TableCell>{u.name}</TableCell><TableCell>{u.email}</TableCell><TableCell>{u.role}</TableCell><TableCell>{u.cpfLast?'***.***.***-'+u.cpfLast:'—'}</TableCell></TableRow>)}</TableBody></Table></div></TabsContent>
<TabsContent value="demo"><div className="section-card"><h2>Dados de demonstração</h2><p>Exemplos identificados no banco e no mapa. Não representam parcerias, endereços exatos ou avaliações reais.</p><div className="flexline" style={{marginTop:20}}><button className="btn" onClick={()=>run('seed',{},'Exemplos adicionados.')}>Adicionar exemplos</button><button className="btn danger" onClick={()=>setConfirm({action:'removeDemo',title:'Remover todos os exemplos?',description:'Apenas as paradas marcadas como demonstração e seus registros relacionados serão excluídos.'})}>Remover todos os exemplos</button></div></div></TabsContent>
<TabsContent value="audit"><div className="section-card"><h2>Auditoria administrativa</h2><Table><TableHeader><TableRow><TableHead>Data</TableHead><TableHead>Ação</TableHead><TableHead>Destino</TableHead></TableRow></TableHeader><TableBody>{data.logs.map((l:any)=><TableRow key={l.id}><TableCell>{new Date(l.createdAt).toLocaleString('pt-BR')}</TableCell><TableCell>{l.action}</TableCell><TableCell>{l.target}</TableCell></TableRow>)}</TableBody></Table></div></TabsContent></Tabs></>}</>}
{view==='about'&&<div className="section-card welcome"><div><div className="eyebrow">ESTRADA, CAFÉ E DESCOBERTA</div><h1>Descubra os melhores sabores da estrada.</h1><p>Conheça paradas participantes, experimente pratos especiais acompanhados de café e ajude a escolher os melhores estabelecimentos da estrada.</p><div className="flexline"><button className="btn primary" onClick={()=>login('TRAVELER',true)}>Sou viajante</button><button className="btn" onClick={()=>login('BUSINESS',true)}>Sou estabelecimento</button></div><p><b>Como funciona?</b><br/>Encontre uma parada → experimente o combo → receba seu token → avalie o prato e o café.</p></div><img src="/coffee.jpg" alt="Uma pausa para o café"/></div>}
</>}</main></div>
<nav className="mobile-nav">{navItems.slice(0,5).map(([key,Icon,label])=><button key={key} className={view===key?'active':''} onClick={()=>nav(key)}><Icon/>{label==='Guia de Estrada'?'Guia':label}</button>)}</nav>
<Sheet open={!!selected} onOpenChange={v=>{if(!v)setSelected(null)}}><SheetContent className="w-full sm:max-w-[520px] overflow-y-auto p-0"><SheetHeader className="sr-only"><SheetTitle>{selected?.name||'Parada'}</SheetTitle><SheetDescription>Combo, localização e avaliação da parada.</SheetDescription></SheetHeader>{selected&&<div className="detail-body"><img src={selected.dishPhoto||'/coffee.jpg'} className="detail-photo" alt={selected.dishName}/><div className="flexline" style={{marginTop:16}}><span className="pill">{selected.road}</span>{!!selected.demo&&<span className="pill gold">Dados demonstrativos</span>}</div><h2>{selected.name}</h2><p><MapPin size={14} style={{display:'inline'}}/> {selected.city} · {selected.state}</p><p>{selected.address}</p><h3>{selected.dishName}</h3><p>{selected.dishDescription}</p><div className="price">{money(camp?.price)} <del>{money(selected.normalPrice)}</del></div><p><Coffee size={16} style={{display:'inline'}}/> {camp?.brand} · {selected.size}</p><p>{selected.ingredients}</p>{selected.notes&&<p>{selected.notes}</p>}<div className="flexline" style={{margin:'20px 0'}}><span className="pill"><Star size={14}/>{grade(selected.score)} · {selected.reviewCount||0} avaliações</span>{selected.rank&&<span className="pill gold">{selected.rank}º no ranking</span>}</div>{!!selected.demo&&<div className="alert">Exemplo de demonstração. Foto ilustrativa e localização aproximada. Não representa parceria comercial.</div>}<a className="btn full-button" href={'https://www.openstreetmap.org/?mlat='+selected.lat+'&mlon='+selected.lng+'#map=15/'+selected.lat+'/'+selected.lng} target="_blank" rel="noreferrer"><MapPin size={16}/>Ver localização no mapa</a><button className="btn primary full-button" onClick={()=>{const b=selected;setSelected(null);open('review',b)}}><Ticket size={16}/>Avaliar esta parada</button><p style={{fontSize:12,marginTop:10}}>Você precisa de um token fornecido pela parada após consumir o combo.</p></div>}</SheetContent></Sheet>
<Dialog open={!!modal} onOpenChange={v=>{if(!v){setModal('');void closeQrFull()}}}><DialogContent ref={qrRef} className={qrFull?'qr-fullscreen':'max-h-[90vh] overflow-y-auto sm:max-w-[680px]'}><DialogHeader><DialogTitle>{({auth:authMode==='login'?'Bom ter você por aqui.':'Sua viagem começa aqui.',business:edit?'Editar parada':'Cadastrar estabelecimento',dish:'Meu combo da campanha',tokens:'Gerar tokens de avaliação',review:'Avalie o combo',campaign:newCampaign?'Nova campanha':'Configurar campanha',question:'Editar pergunta',privacy:'Privacidade e créditos',qr:'Token da parada'} as any)[modal]}</DialogTitle><DialogDescription>{modal==='auth'?'Entre para guardar descobertas e participar da campanha.':modal==='review'?'Dê notas de 1 a 5 para o lanche e o café.':'Bebida de Estrada · Estrada, café e descoberta'}</DialogDescription></DialogHeader>
{formError&&<div className="alert error" role="alert">{formError}</div>}
{modal==='auth'&&<><Tabs value={authMode} onValueChange={v=>{setAuthMode(v);setFormError('')}}><TabsList className="w-full"><TabsTrigger value="login">Entrar</TabsTrigger><TabsTrigger value="register">Criar conta</TabsTrigger></TabsList></Tabs><form onSubmit={e=>submit(e,authMode==='login'?'login':'register',{role,consent})}><div className="form-grid">{authMode==='register'&&<><Field label="Seu nome" name="name" full required/><label className="field full">Tipo de conta<SelectBox value={role} onChange={setRole} options={[{value:'TRAVELER',label:'Viajante'},{value:'BUSINESS',label:'Estabelecimento'}]}/></label>{role==='TRAVELER'&&<Field label="CPF" name="cpf" placeholder="000.000.000-00" required/>}<Field label="Telefone (opcional)" name="phone" type="tel"/></>}<Field label="E-mail" name="email" type="email" required full autoComplete="email"/><Field label="Senha" name="password" type="password" minLength={8} maxLength={128} required full autoComplete={authMode==='login'?'current-password':'new-password'}/></div>{authMode==='register'&&<div className="checkline"><Checkbox id="consent" checked={consent} onCheckedChange={v=>setConsent(v===true)}/><label htmlFor="consent">Li e aceito o tratamento dos meus dados para a campanha.</label><button type="button" className="underline" onClick={()=>open('privacy')}>Política</button></div>}<button className="btn primary full-button" disabled={busy}>{busy?'Aguarde…':authMode==='login'?'Entrar':'Criar minha conta'}</button></form></>}
{modal==='business'&&<form onSubmit={e=>submit(e,'business',{id:edit?.id,photo,acceptBrand:accept})}><div className="form-grid">{[['Nome fantasia','name'],['Razão social','legalName'],['CNPJ','cnpj'],['Responsável','responsible'],['Telefone','phone'],['E-mail','email'],['Endereço','address'],['CEP','cep'],['Cidade','city'],['Estado (UF)','state'],['Região','region'],['Rodovia (opcional)','road'],['Latitude','lat'],['Longitude','lng']].map(([l,n])=><Field key={n} label={l} name={n} defaultValue={edit?.[n]} required={n!=='road'} type={['lat','lng'].includes(n)?'number':n==='email'?'email':'text'} step="any"/>)}</div><button className="btn small" type="button" style={{marginTop:12}} onClick={async e=>{const form=e.currentTarget.form;const p=await locate();if(p&&form){(form.elements.namedItem('lat') as HTMLInputElement).value=String(p[0]);(form.elements.namedItem('lng') as HTMLInputElement).value=String(p[1])}}}><LocateFixed size={14}/>Usar localização atual</button>{uploadField()}<div className="checkline"><Checkbox id="brand" checked={accept} onCheckedChange={v=>setAccept(v===true)}/><label htmlFor="brand">Aceito servir o café oficial {camp?.brand} no combo da campanha.</label></div><button className="btn primary full-button" disabled={busy||uploading}>Salvar estabelecimento</button></form>}
{modal==='dish'&&<form onSubmit={e=>submit(e,'dish',{businessId:edit.id,photo})}><div className="alert">Preço oficial: {money(camp?.price)} · Café: {camp?.brand}{!!camp?.locked&&' · Edição bloqueada para estabelecimentos'}</div><div className="form-grid"><Field label="Nome do prato / combo" name="name" defaultValue={edit?.dishName} full required/><label className="field full">Descrição<textarea name="description" defaultValue={edit?.dishDescription}/></label><Field label="Categoria" name="category" defaultValue={edit?.category} required/><Field label="Preço normal (R$)" name="normalPrice" type="number" min={camp?.price+0.01} step="0.01" defaultValue={edit?.normalPrice} required/><Field label="Ingredientes e alergênicos" name="ingredients" defaultValue={edit?.ingredients} full/><Field label="Tamanho do café" name="size" defaultValue={edit?.size||'150 ml'}/><Field label="Observações" name="notes" defaultValue={edit?.notes}/></div>{uploadField()}<div className="form-actions">{isAdmin&&edit?.dishName&&<button type="button" className="btn danger" onClick={()=>{setModal('');setConfirm({action:'deleteDish',p:{id:edit.id},title:'Excluir combo?',description:'A parada sairá da lista desta campanha até receber um novo combo.'})}}>Excluir combo</button>}<button className="btn primary" disabled={busy||uploading}>Salvar combo</button></div></form>}
{modal==='tokens'&&<form onSubmit={async e=>{e.preventDefault();const count=Number(new FormData(e.currentTarget).get('count'));const d=await run('generateTokens',{businessId:edit.id,count},'Tokens gerados.');if(d)setModal('')}}><p>{edit?.name}</p><div className="wallet-inline"><b>Saldo disponível: {money((data.wallet?.availableCents||0)/100)}</b><span>Cada token desconta R$ 0,50 do saldo.</span><button type="button" className="btn small" onClick={()=>open('wallet',edit)}><WalletCards size={14}/>Adicionar saldo via PIX</button></div><Field label="Quantidade de tokens" name="count" type="number" min="1" max="100" defaultValue="1" required/><p className="bottom-note">Cada token é único, válido nesta campanha e pode ser usado uma vez.</p><button className="btn primary full-button" disabled={busy}>Gerar tokens</button></form>}
{modal==='review'&&<>{reviewStage===0?<><div className="alert">{edit?.name||'Avaliação pelo QR Code'} · {edit?.reviewCampaign?.name||camp?.name}</div><label className="field">Token entregue pela parada<input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="BE-XXXXXXXXXXXX"/></label>{data?.user?.role!=='TRAVELER'&&<><label className="field">Seu CPF<input value={guestCpf} onChange={e=>setGuestCpf(e.target.value)} inputMode="numeric" autoComplete="off" maxLength={14} placeholder="000.000.000-00"/></label><div className="checkline"><Checkbox id="guest-consent" checked={guestConsent} onCheckedChange={v=>setGuestConsent(v===true)}/><label htmlFor="guest-consent">Concordo com o uso do CPF para evitar avaliações duplicadas e vincular esta avaliação à conta que eu criar com o mesmo CPF.</label></div><p className="bottom-note">Não precisa criar conta. Seu CPF é protegido e não é exibido à parada.</p></>}{(edit?.reviewCampaign||camp)?.geoRequired?<p className="bottom-note">A localização é obrigatória. Distância máxima: {(edit?.reviewCampaign||camp).radius} metros.</p>:<p className="bottom-note">A confirmação geográfica está desativada nesta campanha.</p>}<button className="btn primary" disabled={busy||!code||(data?.user?.role!=='TRAVELER'&&(!guestCpf||!guestConsent))} onClick={tokenCheck}>{busy?'Preparando…':'Responder questionário'}</button></>:reviewStage===2?<div className="review-success"><CheckCircle2 size={55}/><h2>Obrigado pela parada!</h2><p>Sua avaliação foi registrada e o ranking foi atualizado.</p>{reviewAccess&&<><p>Ao criar uma conta com o mesmo CPF, esta avaliação aparecerá no seu histórico.</p><button className="btn full-button" onClick={()=>login('TRAVELER',true)}>Criar minha conta</button></>}<button className="btn primary full-button" onClick={()=>{setModal('');nav('ranking')}}>Ver ranking</button></div>:<><div className="review-progress"><div className="flexline spread"><b>5 perguntas. Sua experiência.</b><span>{ratings.filter(Boolean).length}/5</span></div><Progress value={ratings.filter(Boolean).length*20}/><p>3 sobre o lanche · 2 sobre o café</p></div><div className="rating-scale">1 · Muito ruim &nbsp; 2 · Ruim &nbsp; 3 · Bom &nbsp; 4 · Muito bom &nbsp; 5 · Excelente</div>{reviewQuestions.map((q,idx)=><fieldset className="rating-question" key={q.id}><legend><span className={'pill '+(q.category==='coffee'?'gold':'')}>{idx+1}/5 · {q.category==='dish'?'Lanche':'Café'}</span><span>{q.text}</span></legend><RadioGroup className="rating-options" value={ratings[idx]?String(ratings[idx]):''} onValueChange={v=>setRatings(old=>old.map((r,i)=>i===idx?Number(v):r))} aria-label={q.text}>{[1,2,3,4,5].map(n=><label key={n} className={'rating-option '+(ratings[idx]===n?'chosen':'')}><RadioGroupItem className="sr-only" value={String(n)} aria-label={`Nota ${n}: ${q.text}`}/><Star size={18} fill={ratings[idx]===n?'currentColor':'none'}/><span>{n}</span></label>)}</RadioGroup></fieldset>)}<div className="review-submit"><button className="btn primary full-button" disabled={busy||reviewQuestions.length!==5||ratings.includes(0)} onClick={async()=>{const d=await run('review',{businessId:edit.id,campaignId:edit.reviewCampaign?.id||camp.id,code,formId,...(reviewAccess?{reviewAccess}:{}),answers:reviewQuestions.map((q,i)=>({questionId:q.id,rating:ratings[i]})),lat:loc?.[0],lng:loc?.[1]},'');if(d)setReviewStage(2)}}>{busy?'Enviando…':'Enviar avaliação'}</button></div></>}</>}
{modal==='campaign'&&<form onSubmit={e=>submit(e,'campaign',{new:newCampaign,geoRequired,publicRanking,locked,brandLogo:photo})}><div className="form-grid"><Field label="Nome da campanha" name="name" defaultValue={edit?.name} required full/><label className="field">Status<SelectBox value={edit?.status||'rascunho'} onChange={v=>setEdit((x:any)=>({...x,status:v}))} options={['rascunho','inscrições','ativa','encerrada']}/><input type="hidden" name="status" value={edit?.status||'rascunho'}/></label><Field label="Marca oficial do café" name="brand" defaultValue={edit?.brand} required/><Field label="Data inicial" name="start" type="date" defaultValue={edit?.start}/><Field label="Data final" name="end" type="date" defaultValue={edit?.end}/><Field label="Preço oficial (R$)" name="price" type="number" step="0.01" min="0" defaultValue={edit?.price||19.9} required/><div className="field"><span>Peso da nota do combo</span><div className="alert" style={{margin:0}}>60% lanche + 40% café</div><input type="hidden" name="dishWeight" value="60"/></div><Field label="Raio permitido (m)" name="radius" type="number" min="100" max="10000" defaultValue={edit?.radius||500} required/><Field label="Arrecadação registrada (R$)" name="fund" type="number" min="0" step="0.01" defaultValue={edit?.fund||0} required/><Field label="Percentual para premiação" name="prizePercent" type="number" min="0" max="100" defaultValue={edit?.prizePercent??80} required/><Field label="Contribuição por combo (R$)" name="contribution" type="number" min="0" step="0.01" defaultValue={edit?.contribution||0}/><Field label="Desempate (ordem: coffee,count,dish)" name="ties" defaultValue={edit?.ties||'coffee,count,dish'} required full/><Field label="Descrição da marca / campanha" name="description" defaultValue={edit?.description} full/></div><div className="checkline"><Switch checked={geoRequired} onCheckedChange={setGeoRequired} id="geo"/><label htmlFor="geo">Exigir localização ao avaliar</label></div><div className="checkline"><Switch checked={publicRanking} onCheckedChange={setPublicRanking} id="rank"/><label htmlFor="rank">Exibir ranking publicamente</label></div><div className="checkline"><Switch checked={locked} onCheckedChange={setLocked} id="lock"/><label htmlFor="lock">Bloquear alterações dos combos</label></div>{uploadField('Logo da marca')}<button className="btn primary full-button" disabled={busy||uploading}>Salvar campanha</button></form>}
{modal==='question'&&<form onSubmit={e=>submit(e,'editQuestion',{id:edit.id})}><span className="pill">{edit.category==='dish'?'Lanche':'Café'}</span><label className="field" style={{marginTop:16}}>Pergunta<textarea name="text" defaultValue={edit.text} minLength={10} maxLength={350} required rows={4}/></label><p className="bottom-note">A resposta será sempre uma nota de 1 a 5. A alteração vale para novos questionários.</p><button className="btn primary full-button" disabled={busy}>Salvar pergunta</button></form>}

{modal==='wallet'&&<div><div className="eyebrow">SALDO DA PARADA</div><h2>Adicionar saldo via PIX</h2><p>O crédito só aparece depois da confirmação automática do pagamento.</p>{pixDeposit?<div className="pix-box"><p className="token-code">{pixDeposit.copyPaste||'Cobrança criada — aguardando pagamento'}</p>{pixDeposit.qrCode&&<img className="qr" src={pixDeposit.qrCode} alt="QR Code para adicionar saldo"/>}<button className="btn small" onClick={()=>pixDeposit.copyPaste&&navigator.clipboard.writeText(pixDeposit.copyPaste).then(()=>toast.success('Código PIX copiado.'))}><Copy size={14}/>Copiar código PIX</button><p className="bottom-note">Após pagar, aguarde a confirmação do provedor para o saldo ser liberado.</p></div>:<form onSubmit={async e=>{e.preventDefault();setBusy(true);try{const p=Object.fromEntries(new FormData(e.currentTarget));const d=await action('createPixDeposit',{businessId:edit.id,amount:p.amount,idempotencyKey:'site-'+Date.now()});setPixDeposit(d.deposit);await reload();toast.success('Cobrança PIX criada.');}catch(e){setFormError((e as Error).message)}finally{setBusy(false)}}}><Field label="Valor do aporte (R$)" name="amount" type="number" min="1" step="0.01" defaultValue="50" required/><p className="bottom-note">Valor mínimo: R$ 1,00.</p><button className="btn primary full-button" disabled={busy}>{busy?'Criando cobrança…':'Gerar cobrança PIX'}</button></form>}</div>}
{modal==='qr'&&<div style={{textAlign:'center'}}><p className="token-code">{code}</p>{qr&&<img className="qr" src={qr} alt={'QR Code do token '+code}/>}<p>Escaneie, informe seu CPF e avalie. Não precisa ter conta.</p><button className="btn primary full-button" onClick={async()=>{if(qrFull){await closeQrFull();return}setQrFull(true);await qrRef.current?.requestFullscreen?.().catch(()=>{})}}>{qrFull?'Sair da tela cheia':'Exibir QR Code em tela cheia'}</button><button className="btn full-button" onClick={()=>{navigator.clipboard.writeText(code).then(()=>toast.success('Token copiado.')).catch(()=>toast.error('Copie o código exibido acima.'))}}>Copiar código</button></div>}
{modal==='privacy'&&<div className="privacy"><h3>Seus dados na campanha</h3><p>Usamos nome, e-mail, telefone opcional e um identificador derivado do CPF para manter sua conta e impedir votos duplicados. O CPF completo não é armazenado: guardamos um resumo criptográfico com segredo e apenas os dois últimos dígitos para identificação visual.</p><p>Senhas são armazenadas como hashes com salt. A localização, quando exigida pela campanha, confirma a proximidade da parada. Avaliações registram data, hora e resumo protegido do IP para prevenção de fraude.</p><p>O ranking mostra apenas resultados agregados das paradas. Estabelecimentos não recebem o CPF nem a identificação de quem utilizou cada token.</p><p>Os dados são mantidos para operação e auditoria da campanha. Para solicitar acesso, correção ou exclusão dos seus dados, procure a organização responsável pela campanha no estabelecimento participante. A organização deve definir seu contato de privacidade e prazo de retenção antes da abertura ao público.</p><h3>Demonstrações e imagens</h3><p>Exemplos não representam parcerias comerciais. Fotos são ilustrativas. Localizações demonstrativas são aproximadas.</p><p>Foto de pão de queijo: <a className="underline" href="https://commons.wikimedia.org/wiki/File:Pao_de_queijo_brasil.jpg" target="_blank" rel="noreferrer">Acfariac</a>, licença <a className="underline" href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a>. Café: <a className="underline" href="https://unsplash.com/s/photos/coffee-mug" target="_blank" rel="noreferrer">Unsplash</a>. Mapa: © OpenStreetMap contributors.</p></div>}
</DialogContent></Dialog>
<AlertDialog open={!!confirm} onOpenChange={v=>{if(!v)setConfirm(null)}}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{confirm?.title}</AlertDialogTitle><AlertDialogDescription>{confirm?.description}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction onClick={async()=>{await run(confirm.action,confirm.p||{});setConfirm(null)}}>Confirmar</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
</SidebarProvider>;
function uploadField(label='Foto'){return <label className="field full" style={{marginTop:16}}><span className="flexline"><Camera size={15}/>{uploading?'Enviando…':label+' (JPG, PNG ou WebP, até 5 MB)'}</span><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>upload(e.target.files?.[0])} disabled={uploading}/>{photo&&<img className="upload-thumb" src={photo} alt="Foto escolhida"/>}</label>}
function tokenTable(tokens:any[]){return <Table><TableHeader><TableRow>{['Código','Parada','Status','Ações'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{tokens.map(t=><TableRow key={t.id}><TableCell className="token-code">{t.code}</TableCell><TableCell>{t.businessName}</TableCell><TableCell>{t.status}</TableCell><TableCell><div className="flexline"><button className="btn small" onClick={async()=>{setCode(t.code);const q=await import('qrcode');setQr(await q.toDataURL(location.origin+'/?token='+encodeURIComponent(t.code),{width:1024,margin:4,errorCorrectionLevel:'M'}));open('qr')}}>QR Code</button>{t.status==='disponível'&&<button className="btn small danger" onClick={()=>run('cancelToken',{id:t.id},'Token cancelado.')}>Cancelar</button>}</div></TableCell></TableRow>)}</TableBody></Table>}
}
